//! Rust port of the Week 4 Day 9 bounded tool-evidence tests.

#[path = "support/capstone.rs"]
mod capstone;

use std::cell::Cell;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

use serde_json::{Value, json};
use sha2::{Digest, Sha256};
use tiny_llm_agent::protocol::ToolAction;
use tiny_llm_agent::workspace::{ToolPolicy, Workspace};
use tiny_llm_agent::{
    AgentLimits, ArtifactRef, ArtifactStore, BoundedEvidenceWorkspace, ReceiptStore, run_agent,
};

static NEXT_TEMP_DIR: AtomicU64 = AtomicU64::new(1);

struct TestDir(PathBuf);

impl TestDir {
    fn new(label: &str) -> Self {
        let id = NEXT_TEMP_DIR.fetch_add(1, Ordering::Relaxed);
        let path =
            std::env::temp_dir().join(format!("tiny-llm-{label}-{}-{id}", std::process::id()));
        fs::create_dir(&path).expect("create isolated test directory");
        Self(path)
    }

    fn path(&self) -> &Path {
        &self.0
    }
}

impl Drop for TestDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn policy(root: &Path, max_file_bytes: i64) -> ToolPolicy {
    ToolPolicy::new(
        root.to_path_buf(),
        max_file_bytes,
        ToolPolicy::DEFAULT_MAX_LIST_ENTRIES,
        false,
        vec![],
        ToolPolicy::DEFAULT_MAX_WRITE_BYTES,
        ToolPolicy::DEFAULT_COMMAND_TIMEOUT_SECONDS,
    )
    .expect("valid test policy")
}

fn action(tool: &str, arguments: Value) -> ToolAction {
    ToolAction {
        tool: tool.to_owned(),
        arguments: arguments
            .as_object()
            .expect("tool arguments must be an object")
            .clone(),
    }
}

fn read_action(path: &str) -> ToolAction {
    action("read_file", json!({"path": path}))
}

fn payload(observation: &str, prefix: &str) -> Value {
    let encoded = observation
        .strip_prefix(prefix)
        .unwrap_or_else(|| panic!("observation did not start with {prefix:?}: {observation:?}"));
    serde_json::from_str(encoded).expect("observation payload is valid JSON")
}

fn bounded_workspace(
    temp: &TestDir,
    label: &str,
    content: &str,
    max_inline_bytes: i64,
    preview_bytes: i64,
    max_range_bytes: i64,
) -> BoundedEvidenceWorkspace {
    let workspace_root = temp.path().join(format!("{label}-workspace"));
    let artifact_root = temp.path().join(format!("{label}-artifacts"));
    fs::create_dir(&workspace_root).expect("create workspace root");
    fs::create_dir(&artifact_root).expect("create artifact root");
    fs::write(workspace_root.join("build.log"), content.as_bytes()).expect("write build log");
    let workspace = Workspace::new(
        policy(&workspace_root, 32_000),
        None,
        ReceiptStore::new(None).expect("receipt store"),
    );
    let artifacts = ArtifactStore::new(artifact_root).expect("artifact store");
    BoundedEvidenceWorkspace::new(
        workspace,
        artifacts,
        max_inline_bytes,
        preview_bytes,
        max_range_bytes,
    )
    .expect("bounded evidence workspace")
}

fn default_bounded(temp: &TestDir, label: &str, content: &str) -> BoundedEvidenceWorkspace {
    bounded_workspace(
        temp,
        label,
        content,
        BoundedEvidenceWorkspace::DEFAULT_MAX_INLINE_BYTES,
        BoundedEvidenceWorkspace::DEFAULT_PREVIEW_BYTES,
        BoundedEvidenceWorkspace::DEFAULT_MAX_RANGE_BYTES,
    )
}

fn sha256(data: &[u8]) -> String {
    format!("{:x}", Sha256::digest(data))
}

#[test]
fn test_task_0_supplied_capstone_composes_the_completed_active_package() {
    // Child mode exercises the same Rust learner package in another process.
    if let Some(output) = std::env::var_os("TINY_LLM_CAPSTONE_RECORD") {
        let record = capstone::run_capstone();
        fs::write(
            output,
            format!("{}\n", serde_json::to_string(&record).unwrap()),
        )
        .unwrap();
        return;
    }
    let first = capstone::run_capstone();
    assert_eq!(first, capstone::run_capstone());
    let keys = first
        .as_object()
        .unwrap()
        .keys()
        .map(String::as_str)
        .collect::<Vec<_>>();
    assert_eq!(keys, ["artifact", "branches", "compaction", "selection"]);
    let compact = &first["compaction"];
    assert!(compact["tokens_before"].as_i64().unwrap() > compact["tokens_after"].as_i64().unwrap());
    assert!(compact["saved_tokens"].as_i64().unwrap() > 0);
    assert_eq!(compact["receipt_ids"].as_array().unwrap().len(), 2);
    assert_eq!(
        compact["checkpoint_status"]["last_action"],
        r#"{"path":"build.log","tool":"read_file"}"#
    );
    let branches = first["branches"].as_array().unwrap();
    assert_eq!(branches.len(), 2);
    assert_eq!(branches[0]["name"], "validate-only");
    assert_eq!(branches[1]["name"], "try-extra-edit");
    assert_eq!(branches[0]["evaluation"]["passed"], true);
    assert_eq!(branches[1]["evaluation"]["passed"], false);
    for branch in branches {
        let reused = branch["reused_tokens"].as_i64().unwrap();
        assert!(reused > 0);
        assert_eq!(branch["avoided_prefill_tokens"], reused);
        assert_eq!(branch["layer_offsets"], json!([reused, reused]));
    }
    let selection = &first["selection"];
    assert_eq!(selection["selected_name"], "validate-only");
    assert_eq!(selection["app_py_sha256"], sha256(b"answer = 2\n"));
    assert_eq!(
        selection["modified_files"],
        json!({"base":["app.py"],"selected_branch":[]})
    );
    let base_ids = selection["base_receipt_ids"].as_array().unwrap();
    let selected_ids = selection["selected_receipt_ids"].as_array().unwrap();
    assert_eq!(base_ids.len(), 2);
    assert_eq!(selected_ids.len(), 3);
    assert_eq!(&selected_ids[..2], base_ids);
    let artifact = &first["artifact"];
    assert_eq!(
        artifact["artifact_id"],
        format!("artifact-{}", artifact["sha256"].as_str().unwrap())
    );
    assert!(
        artifact["full_byte_count"].as_u64().unwrap()
            > artifact["model_visible_observation_byte_count"]
                .as_u64()
                .unwrap()
    );
    assert_eq!(artifact["range_text"], "ERROR code=E42 dependency mismatch");
    assert_eq!(
        artifact["range_byte_count"].as_u64().unwrap(),
        artifact["range_text"].as_str().unwrap().len() as u64
    );
    assert_eq!(
        artifact["range_end"].as_u64().unwrap() - artifact["range_start"].as_u64().unwrap(),
        artifact["range_byte_count"].as_u64().unwrap()
    );

    let temporary = tempfile::tempdir().unwrap();
    let executable = std::env::current_exe().unwrap();
    let mut records = Vec::new();
    for name in ["first-executable-path", "second-executable-path"] {
        let alias = temporary.path().join(name);
        std::os::unix::fs::symlink(&executable, &alias).unwrap();
        let record_path = temporary.path().join(format!("{name}.json"));
        let output = std::process::Command::new(&alias)
            .args([
                "--exact",
                "test_task_0_supplied_capstone_composes_the_completed_active_package",
            ])
            .env("TINY_LLM_CAPSTONE_RECORD", &record_path)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "{}\n{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(output.stderr.is_empty());
        let record = fs::read(&record_path).unwrap();
        assert!(record.ends_with(b"\n"));
        assert_eq!(serde_json::from_slice::<Value>(&record).unwrap(), first);
        for forbidden in [
            &executable,
            &alias,
            &temporary.path().to_path_buf(),
            &PathBuf::from(env!("CARGO_MANIFEST_DIR")),
        ] {
            assert!(!String::from_utf8_lossy(&record).contains(forbidden.to_str().unwrap()));
        }
        records.push(record);
    }
    assert_eq!(records[0], records[1]);
    assert_eq!(sha256(&records[0]), sha256(&records[1]));
}

#[test]
fn test_task_1_artifact_store_preserves_exact_bytes_and_identity() {
    let temp = TestDir::new("day9-artifact-store");
    let artifact_root = temp.path().join("artifacts");
    fs::create_dir(&artifact_root).expect("create artifact root");
    let mut store = ArtifactStore::new(artifact_root.clone()).expect("artifact store");
    let result = format!("α\n{}", "build output\n".repeat(40));
    let data = result.as_bytes();

    let record = store.put(&result).expect("store result");

    let digest = sha256(data);
    assert_eq!(
        record,
        ArtifactRef::new(
            format!("artifact-{digest}"),
            data.len() as i64,
            digest.clone(),
        )
        .expect("valid artifact ref")
    );
    assert_eq!(
        fs::read(artifact_root.join(&record.artifact_id)).expect("read artifact"),
        data
    );
    assert_eq!(
        store
            .read_range(&record.artifact_id, 2, 17)
            .expect("read byte range"),
        data[2..17]
    );
    assert_eq!(store.put(&result).expect("idempotent put"), record);

    let error = ArtifactRef::new(
        "artifact-UPPER".to_owned(),
        data.len() as i64,
        digest.clone(),
    )
    .unwrap_err();
    assert!(error.to_string().contains("artifact id"));
    let error = ArtifactRef::new(record.artifact_id.clone(), -1, digest.clone()).unwrap_err();
    assert!(error.to_string().contains("byte count"));
    let error = ArtifactRef::new(
        record.artifact_id.clone(),
        data.len() as i64,
        "not-a-digest".to_owned(),
    )
    .unwrap_err();
    assert!(error.to_string().contains("digest"));
    let other_digest = sha256(b"other");
    let error = ArtifactRef::new(record.artifact_id, data.len() as i64, other_digest).unwrap_err();
    assert!(error.to_string().contains("must match"));
}

#[test]
fn test_task_2_oversized_result_becomes_bounded_verifiable_observation() {
    let temp = TestDir::new("day9-externalize");
    let content = format!("HEAD----{}----TAIL", "x".repeat(3_000));
    let mut bounded = bounded_workspace(&temp, "ascii", &content, 512, 8, 24);

    let observation = bounded
        .execute(&read_action("build.log"), None)
        .expect("externalize oversized result");
    let observed = payload(&observation, "Tool result externalized:\n");

    let data = content.as_bytes();
    let digest = sha256(data);
    let artifact_id = format!("artifact-{digest}");
    let expected_path = bounded
        .artifacts
        .range_path(&artifact_id, 0, 24)
        .expect("range path");
    assert_eq!(
        observed,
        json!({
            "artifact_id": artifact_id,
            "byte_count": data.len(),
            "head_preview": "HEAD----",
            "head_range": [0, 8],
            "omitted_range": [8, data.len() - 8],
            "range_request": {"path": expected_path, "tool": "read_file"},
            "sha256": digest,
            "tail_preview": "----TAIL",
            "tail_range": [data.len() - 8, data.len()],
        })
    );
    assert!(observation.len() <= bounded.max_inline_bytes as usize);
    assert!(observation.len() < content.len());
    assert_eq!(
        fs::read(
            bounded
                .artifacts
                .root
                .join(observed["artifact_id"].as_str().unwrap())
        )
        .expect("read stored artifact"),
        data
    );

    let unicode_content = format!("αβγ{}δεζ", "x".repeat(1_000));
    let mut unicode = bounded_workspace(&temp, "unicode", &unicode_content, 512, 5, 24);
    let rendered = unicode
        .execute(&read_action("build.log"), None)
        .expect("externalize unicode result");
    let observed = payload(&rendered, "Tool result externalized:\n");
    assert!(
        !observed["head_preview"]
            .as_str()
            .unwrap()
            .contains('\u{fffd}')
    );
    assert!(
        !observed["tail_preview"]
            .as_str()
            .unwrap()
            .contains('\u{fffd}')
    );
    assert!(rendered.len() <= unicode.max_inline_bytes as usize);
}

