#[test]
fn test_task_4_range_failures_are_ordinary_and_do_not_fall_through() {
    for (index, (path_template, message)) in [
        (".tool-artifacts/not-an-id/bytes/0-4", "path is malformed"),
        ("{artifact}/bytes/-1-2", "path is malformed"),
        ("{artifact}/bytes/9-2", "0 <= start < end"),
        ("{artifact}/bytes/0-99", "exceeds 16 bytes"),
        ("{artifact}/bytes/0-16", "stored byte count"),
    ]
    .into_iter()
    .enumerate()
    {
        let temp = TestDir::new(&format!("day9-range-failure-{index}"));
        let mut bounded = bounded_workspace(&temp, "range", "short", 512, 4, 16);
        let record = bounded.artifacts.put("short").expect("store artifact");
        let artifact_prefix = format!(".tool-artifacts/{}", record.artifact_id);
        let path = path_template.replace("{artifact}", &artifact_prefix);
        let learner_path = bounded.workspace.policy.root.join(&path);
        fs::create_dir_all(learner_path.parent().expect("path parent"))
            .expect("create fall-through path");
        fs::write(&learner_path, b"learner-secret").expect("write fall-through secret");

        let result = bounded
            .execute(&read_action(&path), None)
            .expect("range failure is model-visible");
        assert!(result.starts_with("error: "));
        assert!(result.contains(message), "{path}: {result}");
        assert!(!result.contains("short"));
        assert!(!result.contains("learner-secret"));
    }
}

