#[test]
fn test_task_4_unknown_store_and_tampering_do_not_leak_artifacts() {
    let temp = TestDir::new("day9-store-isolation");
    let mut bounded = bounded_workspace(&temp, "original", "classified diagnostic", 512, 4, 16);
    let record = bounded
        .artifacts
        .put("classified diagnostic")
        .expect("store classified artifact");
    let path = bounded
        .artifacts
        .range_path(&record.artifact_id, 0, 10)
        .expect("range path");

    let unrelated_root = temp.path().join("unrelated-artifacts");
    fs::create_dir(&unrelated_root).expect("create unrelated artifact root");
    let unrelated_workspace = Workspace::new(
        policy(&bounded.workspace.policy.root, 32_000),
        None,
        ReceiptStore::new(None).unwrap(),
    );
    let mut unrelated = BoundedEvidenceWorkspace::new(
        unrelated_workspace,
        ArtifactStore::new(unrelated_root).unwrap(),
        512,
        4,
        16,
    )
    .unwrap();
    let missing = unrelated
        .execute(&read_action(&path), None)
        .expect("unknown artifact is model-visible");
    assert_eq!(missing, "error: artifact is not available in this store");
    assert!(!missing.contains(&record.artifact_id));
    assert!(!missing.contains("classified"));

    let unicode_record = bounded.artifacts.put("αβγ").expect("store unicode");
    let split_path = bounded
        .artifacts
        .range_path(&unicode_record.artifact_id, 1, 3)
        .expect("range path");
    let split = bounded
        .execute(&read_action(&split_path), None)
        .expect("misalignment is model-visible");
    assert_eq!(split, "error: artifact range does not align to UTF-8 text");

    fs::write(
        bounded.artifacts.root.join(&record.artifact_id),
        b"tampered",
    )
    .expect("tamper artifact");
    let tampered = bounded
        .execute(&read_action(&path), None)
        .expect("tampering is model-visible");
    assert_eq!(
        tampered,
        "error: artifact digest does not match its recorded identity"
    );
    assert!(!tampered.contains("classified"));
}

#[test]
fn test_task_4_range_cap_plus_one_is_rejected() {
    let temp = TestDir::new("day9-range-cap-plus-one");
    let mut bounded = bounded_workspace(&temp, "range", &"a".repeat(100), 512, 4, 16);
    let record = bounded
        .artifacts
        .put(&"a".repeat(100))
        .expect("store artifact");
    let path = bounded
        .artifacts
        .range_path(&record.artifact_id, 0, 17)
        .expect("range path");
    let result = bounded
        .execute(&read_action(&path), None)
        .expect("cap failure is model-visible");
    assert_eq!(result, "error: artifact range exceeds 16 bytes");
}

#[test]
fn test_task_5_existing_agent_loop_retrieves_evidence_then_continues() {
    let temp = TestDir::new("day9-agent-loop");
    let diagnostic = "ERROR code=E42 dependency mismatch";
    let content = format!(
        "head\n{}{}\n{}\ntail",
        "x".repeat(500),
        diagnostic,
        "y".repeat(500)
    );
    let mut bounded = bounded_workspace(&temp, "loop", &content, 512, 8, 64);
    let digest = sha256(content.as_bytes());
    let artifact_id = format!("artifact-{digest}");
    let start = content.find(diagnostic).expect("diagnostic offset");
    let end = start + diagnostic.len();
    let range_path = bounded
        .artifacts
        .range_path(&artifact_id, start as i64, end as i64)
        .expect("range path");
    let responses = [
        r#"{"tool":"read_file","path":"build.log"}"#.to_owned(),
        json!({"tool": "read_file", "path": range_path}).to_string(),
        r#"{"final":"The requested range contains diagnostic E42."}"#.to_owned(),
    ];
    let response_index = Cell::new(0usize);
    let mut generate = |_messages: &[tiny_llm_agent::generation::Message]| {
        let index = response_index.get();
        response_index.set(index + 1);
        responses[index].clone()
    };
    let limits = AgentLimits::new(
        3,
        AgentLimits::DEFAULT_MAX_CONTEXT_CHARS,
        AgentLimits::DEFAULT_MAX_INVALID_ACTIONS,
        AgentLimits::DEFAULT_MAX_IDENTICAL_ACTIONS,
    )
    .expect("agent limits");

    let run = run_agent(
        Some("Inspect the large build log and retrieve the diagnostic range."),
        &mut generate,
        &mut bounded,
        Some(&limits),
        None,
    )
    .expect("agent run");

    assert!(run.completed);
    assert_eq!(
        run.final_.as_deref(),
        Some("The requested range contains diagnostic E42.")
    );
    assert_eq!(run.events.len(), 3);
    assert!(
        !run.events[0]
            .result
            .as_deref()
            .unwrap()
            .contains(diagnostic)
    );
    let range = payload(
        run.events[1].result.as_deref().unwrap(),
        "Artifact range:\n",
    );
    assert_eq!(range["artifact_id"], artifact_id);
    assert_eq!(range["start"], start);
    assert_eq!(range["end"], end);
    assert_eq!(range["data"], diagnostic);
    assert_eq!(
        fs::read(bounded.artifacts.root.join(&artifact_id)).expect("read full artifact"),
        content.as_bytes()
    );
}

#[test]
fn test_task_6_small_and_error_results_remain_inline_and_state_is_delegated() {
    let temp = TestDir::new("day9-inline-delegation");
    let mut bounded = bounded_workspace(&temp, "small", "small result\n", 512, 8, 16);
    let result = bounded
        .execute(&read_action("build.log"), None)
        .expect("read small result");
    assert_eq!(result, "small result\n");
    assert!(std::ptr::eq(bounded.policy(), &bounded.workspace.policy));
    assert_eq!(
        bounded.available_tools(),
        bounded.workspace.available_tools()
    );
    assert!(bounded.modified_files().is_empty());
    assert_eq!(
        fs::read_dir(&bounded.artifacts.root)
            .expect("list artifact root")
            .count(),
        0
    );

    // Rust's concrete Workspace cannot be monkeypatched. An unknown, very long
    // tool name produces the same oversized `error:` delegation case.
    let long_tool = format!("missing-{}", "x".repeat(1_000));
    let long_error = bounded
        .execute(&action(&long_tool, json!({})), None)
        .expect("workspace error is model-visible");
    assert!(long_error.starts_with("error:"));
    assert!(long_error.len() > 512);
    assert_eq!(
        fs::read_dir(&bounded.artifacts.root)
            .expect("list artifact root")
            .count(),
        0
    );

    let invalid_workspace_root = temp.path().join("invalid-workspace");
    let invalid_artifact_root = temp.path().join("invalid-artifacts");
    fs::create_dir(&invalid_workspace_root).unwrap();
    fs::create_dir(&invalid_artifact_root).unwrap();
    let workspace = Workspace::new(
        policy(&invalid_workspace_root, 32_000),
        None,
        ReceiptStore::new(None).unwrap(),
    );
    let artifacts = ArtifactStore::new(invalid_artifact_root).unwrap();
    let error = BoundedEvidenceWorkspace::new(workspace, artifacts, 511, 64, 512)
        .err()
        .expect("inline cap below minimum must fail");
    assert!(error.to_string().contains("at least 512"));

    let preview_workspace_root = temp.path().join("preview-workspace");
    let preview_artifact_root = temp.path().join("preview-artifacts");
    fs::create_dir(&preview_workspace_root).unwrap();
    fs::create_dir(&preview_artifact_root).unwrap();
    let workspace = Workspace::new(
        policy(&preview_workspace_root, 32_000),
        None,
        ReceiptStore::new(None).unwrap(),
    );
    let artifacts = ArtifactStore::new(preview_artifact_root).unwrap();
    let error = BoundedEvidenceWorkspace::new(workspace, artifacts, 512, 513, 512)
        .err()
        .expect("preview over inline cap must fail");
    assert!(error.to_string().contains("must not exceed"));
}
